-- Live video webcams harvested from worldcam.tv's public catalog (one-time).
-- Pointers to public YouTube live streams (video id) + coordinates + a coarse
-- continent (region) for filtering. Kept coastal categories, dropped
-- animal/zoo/aquarium/nature/mountain cams and non-visual streams (music/radio/
-- DJ etc.). We store pointers, not content.
DROP TABLE IF EXISTS cams;
CREATE TABLE cams (
  id          SERIAL PRIMARY KEY,
  youtube_id  TEXT UNIQUE NOT NULL,
  title       TEXT NOT NULL,
  lat         DOUBLE PRECISION NOT NULL,
  lon         DOUBLE PRECISION NOT NULL,
  city        TEXT,
  country     TEXT,
  category    TEXT,
  region      TEXT
);
CREATE INDEX cams_lat_lon_idx ON cams (lat, lon);
CREATE INDEX cams_region_idx ON cams (region);

ON CONFLICT (youtube_id) DO NOTHING;
